actions.script:
found = false
const L = (text) => ec.l10n.localize(text)
const notFound = () => { ec.message.addError(L('Page not found')) }
if (wikiPageId) {
    const row = ec.entity.find('moqui.resource.wiki.WikiPage').condition('wikiPageId', wikiPageId).one()
    if (row == null) return notFound()
    wikiSpaceId = row.wikiSpaceId
    pagePath = row.pagePath || ''
}
if (!wikiSpaceId) return notFound()
const space = ec.entity.find('moqui.resource.wiki.WikiSpace').condition('wikiSpaceId', wikiSpaceId).useCache(true).one()
if (space == null || !space.rootPageLocation) return notFound()
pagePath = String(pagePath || '').split('/').map((part) => part.trim()).filter((part) => part).join('/')
const refOut = ec.service.sync().name('org.moqui.resource.WikiServices.get#WikiPageReference')
        .parameters({wikiSpaceId: wikiSpaceId, pagePath: pagePath}).call()
if (ec.message.hasError() || refOut == null) { ec.message.clearErrors(); return notFound() }
const ref = refOut.pageReference
wikiSpaceId = refOut.wikiSpaceId
pagePath = refOut.pagePath || ''
wikiPageId = refOut.wikiPageId || null
const rights = ec.service.sync().name('org.moqui.resource.WikiServices.get#WikiPageAccess')
        .parameters(wikiPageId ? {wikiPageId: wikiPageId} : {wikiSpaceId: wikiSpaceId}).call() || {}
if (!rights.canView) {
    ec.logger.info(`Knowledge: ${wikiSpaceId}/${pagePath} is not visible to user ${ec.user.username}`)
    return notFound()
}
if (need === 'admin' && !rights.canAdmin) { ec.message.addError(L('Only an administrator of this space may do that')); return }
if (need === 'update' && !rights.canUpdate) {
    ec.message.addError(rights.readOnly ? L('This space is a read-only mirror') : L('You may not change this page'))
    return
}
found = true
wikiPage = refOut.wikiPage ? refOut.wikiPage.getMap() : null
wikiSpace = space.getMap()
pageReference = ref
exists = !!(ref != null && ref.exists)
pageName = pagePath ? pagePath.substring(pagePath.lastIndexOf('/') + 1) : (space.description || wikiSpaceId)
isNotes = String(wikiSpaceId).startsWith('NOTES_')
isMyNotes = !!ec.user.userId && wikiSpaceId === 'NOTES_' + ec.user.userId
access = {canView: !!rights.canView, canUpdate: !!rights.canUpdate, canAdmin: !!rights.canAdmin, storage: rights.storage || null,
    repositoryId: rights.repositoryId || null, repositoryKind: rights.repositoryKind || null, readOnly: !!rights.readOnly}

spaceList = []
recentList = []
reviewCount = 0
failedParts = []
const L = (text) => ec.l10n.localize(text)
const storageText = (access) => access.storage === 'git' ? (access.repositoryKind === 'remote' ? L('Git mirror (read only)')
        : access.repositoryKind === 'local' ? L('Git on disk') : L('Git in the database')) : L('Database files')
const scope = ec.service.sync().name('org.moqui.resource.WikiServices.get#WikiViewScope').call() || {}
const viewIds = new Set(Array.from(scope.viewSpaceIdList || []))
for (const space of Array.from(ec.entity.find('moqui.resource.wiki.WikiSpace').orderBy('description,wikiSpaceId').list())) {
    if (!viewIds.has(space.wikiSpaceId) || String(space.wikiSpaceId).startsWith('NOTES_')) continue
    const access = ec.service.sync().name('org.moqui.resource.WikiServices.get#WikiPageAccess').parameter('wikiSpaceId', space.wikiSpaceId).call() || {}
    spaceList.push({wikiSpaceId: space.wikiSpaceId, description: space.description || space.wikiSpaceId, canUpdate: !!access.canUpdate,
        canAdmin: !!access.canAdmin, storage: access.storage || null, repositoryKind: access.repositoryKind || null, readOnly: !!access.readOnly,
        storageText: storageText(access), restrictView: space.restrictView === 'Y', restrictUpdate: space.restrictUpdate === 'Y'})
}
const ids = spaceList.map((space) => space.wikiSpaceId)
let last = null
try { last = ec.user.getPreference('KNOWLEDGE_SPACE') } catch (err) { last = null }
defaultWikiSpaceId = wikiSpaceId && ids.includes(wikiSpaceId) ? wikiSpaceId : (last && ids.includes(last) ? last : (ids[0] || null))
try {
    recentList = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#RecentPages').parameters({limit: 6, includeNotes: false}).call()?.pageList || []
} catch (err) { ec.logger.warn(`Knowledge setup: the recent pages not read: ${err}`); failedParts.push('recent') }
ec.message.pushErrors()
try {
    reviewCount = ec.service.sync().name('org.moqui.resource.WikiServices.find#WikiPageReviews').parameter('filter', 'toDo').call()?.reviewCount || 0
    if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
} catch (err) { ec.logger.warn(`Knowledge setup: the reviews not counted: ${err}`); failedParts.push('reviews') }
finally { ec.message.clearErrors(); ec.message.popErrors() }
const account = ec.user.userAccount
me = {userId: ec.user.userId, name: account ? (account.userFullName || account.username) : ec.user.username,
    isAdmin: ec.user.isInGroup('ADMIN'), notesSpaceId: ec.user.userId ? 'NOTES_' + ec.user.userId : null}

childList = []
const ref = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#PageRef').parameters({wikiSpaceId: wikiSpaceId,
    pagePath: pagePath || '', need: 'view'}).call()
if (ec.message.hasError() || !ref?.found || !ref.exists) return
const base = ref.pagePath || ''
const scope = ec.service.sync().name('org.moqui.resource.WikiServices.get#WikiViewScope').call() || {}
const hidden = new Set(Array.from(scope.hiddenPageIdList || []))
const rows = new Map()
for (const row of Array.from(ec.entity.find('moqui.resource.wiki.WikiPage').condition('wikiSpaceId', ref.wikiSpaceId).list()))
    rows.set(row.pagePath || '', row)
for (const childRef of Array.from(ref.pageReference.getChildren() || [])) {
    if (!childRef.isFile()) continue
    const fileName = String(childRef.getFileName())
    if (fileName.startsWith('.')) continue
    const dot = fileName.lastIndexOf('.')
    const name = dot > 0 ? fileName.substring(0, dot) : fileName
    const path = (base ? base + '/' : '') + name
    const row = rows.get(path)
    if (row && hidden.has(row.wikiPageId)) continue
    let hasChildren = false
    try { hasChildren = Array.from(childRef.getChildren() || []).some((child) => child.isFile()) } catch (err) { hasChildren = false }
    childList.push({pagePath: path, name: name, wikiPageId: row ? row.wikiPageId : null, sequenceNum: row?.sequenceNum ?? 50,
        restricted: row?.restrictView === 'Y', hasChildren: hasChildren})
}
childList.sort((left, right) => Number(left.sequenceNum) - Number(right.sequenceNum) || left.name.localeCompare(right.name))

failedParts = []
page = null
const L = (text) => ec.l10n.localize(text)
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const text = String(value)
    if (/^-?\d+$/.test(text)) return Number(text)
    const parsed = Date.parse(text)
    return Number.isNaN(parsed) ? null : parsed
}
const fmt = (millis, pattern) => millis == null ? '' : ec.l10n.format(new Date(Number(millis)), pattern)
const short = (name) => name == null ? null : String(name).length > 12 ? String(name).substring(0, 10) : String(name)
const users = {}
const userName = (userId) => {
    if (!userId) return null
    if (!(userId in users)) {
        const account = ec.entity.find('moqui.security.UserAccount').condition('userId', userId).useCache(true).disableAuthz().one()
        users[userId] = account ? (account.userFullName || account.username || userId) : userId
    }
    return users[userId]
}
const ref = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#PageRef').parameters({wikiPageId: wikiPageId || null,
    wikiSpaceId: wikiSpaceId || null, pagePath: pagePath || '', need: 'view'}).call()
if (ec.message.hasError() || !ref?.found) return
const part = (name, run) => {
    ec.message.pushErrors()
    try {
        run()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    } catch (err) {
        ec.logger.warn(`Knowledge page ${ref.wikiSpaceId}/${ref.pagePath || ''}: ${name} not read: ${err && err.message ? err.message : err}`)
        failedParts.push(name)
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
}
const space = ref.wikiSpace
const row = ref.wikiPage
const path = ref.pagePath || ''
const segments = path ? path.split('/') : []
const crumbs = [{label: space.description || ref.wikiSpaceId, pagePath: ''}]
segments.forEach((segment, index) => { if (index < segments.length - 1) crumbs.push({label: segment, pagePath: segments.slice(0, index + 1).join('/')}) })
page = {wikiPageId: ref.wikiPageId || null, wikiSpaceId: ref.wikiSpaceId, pagePath: path, pageName: ref.pageName,
    parentPath: segments.length > 1 ? segments.slice(0, -1).join('/') : '', spaceDescription: space.description || ref.wikiSpaceId,
    exists: !!ref.exists, isRoot: !path, isNotes: !!ref.isNotes, isMyNotes: !!ref.isMyNotes, canUpdate: !!ref.access.canUpdate,
    canAdmin: !!ref.access.canAdmin, storage: ref.access.storage, repositoryKind: ref.access.repositoryKind, readOnly: !!ref.access.readOnly,
    restrictView: row?.restrictView === 'Y', restrictUpdate: row?.restrictUpdate === 'Y',
    spaceRestrictView: space.restrictView === 'Y', spaceRestrictUpdate: space.restrictUpdate === 'Y',
    publishedVersionName: row?.publishedVersionName || null, publishedShort: short(row?.publishedVersionName), breadcrumbs: crumbs,
    text: '', title: ref.pageName, tags: [], pinned: false, links: [], backlinks: [], attachments: [], reviews: [], records: [],
    following: false, versionCount: 0}
page.restricted = page.restrictView || page.spaceRestrictView
if (!ref.exists) return
const pageRef = ref.pageReference
let text
if (versionName) {
    text = pageRef.getText(versionName)
    if (text == null) { page = null; ec.message.addError(L('That version of the page was not found')); return }
} else {
    text = pageRef.getText() ?? ''
}
page.text = text
const heading = String(text).match(/^\s{0,3}#{1,6}\s+(.+?)\s*#*\s*$/m)
page.title = heading ? heading[1].replace(/[*_`]/g, '').trim() : ref.pageName
const versioned = pageRef.supportsVersion()
const current = versioned ? (pageRef.getCurrentVersion()?.versionName ?? null) : null
page.currentVersionName = current
page.currentShort = short(current)
page.versionName = versionName || current
page.viewingOld = !!versionName && versionName !== current
page.viewShort = short(versionName)
page.isPublished = !!page.publishedVersionName && page.publishedVersionName === current
part('lastChange', () => {
    const change = ec.resource.getLastChange(pageRef.location)
    const millis = toMillis(change?.date)
    page.lastChange = change ? {millis: millis, dateText: fmt(millis, 'MMM d, yyyy h:mm a'), userId: change.userId || null,
        userName: userName(change.userId), note: change.note ? String(change.note).split('\n')[0] : null,
        versionName: change.versionName || null, versionShort: short(change.versionName)} : null
    if (versioned) page.versionCount = Array.from(pageRef.getVersionHistory() || []).length
})
if (ref.wikiPageId) {
    part('tags', () => {
        const dateFilter = ec.entity.conditionFactory.makeConditionDate('fromDate', 'thruDate', null)
        const ids = Array.from(ec.entity.find('moqui.resource.wiki.WikiPageCategoryMember').condition('wikiPageId', ref.wikiPageId)
                .condition(dateFilter).list()).map((member) => member.wikiPageCategoryId)
        page.pinned = ids.includes('Pinned')
        page.tags = ids.filter((id) => id !== 'Pinned').map((id) => ec.entity.find('moqui.resource.wiki.WikiPageCategory')
                .condition('wikiPageCategoryId', id).useCache(true).one()?.categoryName || id).sort((a, b) => a.localeCompare(b))
    })
    part('links', () => {
        const links = ec.service.sync().name('org.moqui.resource.WikiServices.get#WikiPageLinks').parameter('wikiPageId', ref.wikiPageId).call()
        page.links = Array.from(links?.linkList || []).map((link) => ({toWikiSpaceId: link.toWikiSpaceId, toPagePath: link.toPagePath || '',
            toWikiPageId: link.toWikiPageId || null, linkText: link.linkText, linkTarget: link.linkTarget, found: !!link.found}))
        const back = ec.service.sync().name('org.moqui.resource.WikiServices.get#WikiPageBacklinks').parameter('wikiPageId', ref.wikiPageId).call()
        page.backlinks = Array.from(back?.backlinkList || []).filter((link) => !String(link.wikiSpaceId).startsWith('NOTES_') || link.wikiSpaceId === 'NOTES_' + ec.user.userId)
                .map((link) => ({wikiPageId: link.wikiPageId, wikiSpaceId: link.wikiSpaceId, spaceDescription: link.spaceDescription,
                    pagePath: link.pagePath || '', pageName: link.pageName, linkText: link.linkText}))
    })
    part('attachments', () => {
        const directory = pageRef.getChild('_attachments')
        const entries = directory != null && directory.exists ? Array.from(directory.getDirectoryEntries() || []) : []
        page.attachments = entries.filter((entry) => entry.isFile()).map((entry) => {
            const size = entry.getSize()
            const modified = toMillis(entry.getLastModified())
            const type = entry.getContentType() || ''
            return {filename: entry.getFileName(), contentType: type, size: size ?? null,
                sizeText: size == null ? '' : size < 1024 ? size + ' B' : size < 1048576 ? Math.round(size / 1024) + ' KB' : (size / 1048576).toFixed(1) + ' MB',
                dateText: fmt(modified, 'MMM d, yyyy'), isImage: /^image\//.test(type)}
        }).sort((a, b) => a.filename.localeCompare(b.filename))
    })
    part('reviews', () => {
        const out = ec.service.sync().name('ironstone.commons.KnowledgeServices.find#Reviews').parameters({filter: 'all', wikiPageId: ref.wikiPageId,
            statusId: 'WprRequested'}).call()
        page.reviews = Array.from(out?.reviewList || [])
    })
    part('records', () => {
        const records = []
        const add = (entityName, id) => {
            const info = ec.service.sync().name('ironstone.shared.ChatterServices.get#RecordInfo').parameters({recordEntityName: entityName, recordId: id}).call()
            if (info?.visible) records.push({recordEntityName: entityName, recordId: id, title: info.title, typeLabel: info.typeLabel,
                url: info.url, icon: info.icon})
        }
        for (const link of Array.from(ec.entity.find('mantle.work.effort.WikiPageWorkEffort').condition('wikiPageId', ref.wikiPageId).list()))
            add('mantle.work.effort.WorkEffort', link.workEffortId)
        for (const link of Array.from(ec.entity.find('mantle.request.WikiPageRequest').condition('wikiPageId', ref.wikiPageId).list()))
            add('mantle.request.Request', link.requestId)
        page.records = records
    })
    part('follow', () => {
        page.following = !!ec.user.userId && ec.entity.find('mantle.party.communication.RecordFollower').condition({
            recordEntityName: 'moqui.resource.wiki.WikiPage', recordId: ref.wikiPageId, userId: ec.user.userId}).one() != null
    })
    if (!page.viewingOld) part('recent', () => {
        ec.service.sync().name('ironstone.commons.KnowledgeServices.record#PageOpened').parameters({wikiPageId: ref.wikiPageId,
            wikiSpaceId: ref.wikiSpaceId}).call()
    })
}

if (!ec.user.userId) return
let list = []
try { list = JSON.parse(ec.user.getPreference('KNOWLEDGE_RECENT') || '[]') } catch (err) { list = [] }
if (!Array.isArray(list)) list = []
const now = Number(String(ec.user.nowTimestamp))
list = [{id: wikiPageId, at: now}].concat(list.filter((item) => item && item.id && item.id !== wikiPageId)).slice(0, 20)
ec.user.setPreference('KNOWLEDGE_RECENT', JSON.stringify(list))
if (wikiSpaceId && !String(wikiSpaceId).startsWith('NOTES_') && ec.user.getPreference('KNOWLEDGE_SPACE') !== wikiSpaceId)
    ec.user.setPreference('KNOWLEDGE_SPACE', wikiSpaceId)

pageList = []
failed = false
const me = ec.user.userId
if (!me) return
const L = (text) => ec.l10n.localize(text)
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    const text = String(value)
    if (/^-?\d+$/.test(text)) return Number(text)
    const parsed = Date.parse(text)
    return Number.isNaN(parsed) ? null : parsed
}
const fmt = (millis, pattern) => ec.l10n.format(new Date(Number(millis)), pattern)
const items = new Map()
const note = (id, millis, kind) => {
    if (!id || millis == null) return
    const known = items.get(id)
    if (!known || known.millis < millis) items.set(id, {millis: millis, kind: kind})
}
try {
    let viewed = []
    try { viewed = JSON.parse(ec.user.getPreference('KNOWLEDGE_RECENT') || '[]') } catch (err) { viewed = [] }
    for (const item of Array.isArray(viewed) ? viewed : []) if (item && item.id) note(String(item.id), Number(item.at) || 0, 'opened')
} catch (err) { failed = true; ec.logger.warn(`Recent pages: the opened pages not read: ${err}`) }
try {
    for (const row of Array.from(ec.entity.find('moqui.resource.wiki.WikiPageHistory').condition('userId', me)
            .orderBy('-changeDateTime').limit(200).list())) note(row.wikiPageId, toMillis(row.changeDateTime), 'changed')
} catch (err) { failed = true; ec.logger.warn(`Recent pages: the changed pages not read: ${err}`) }
try {
    const scope = ec.service.sync().name('org.moqui.resource.WikiServices.get#WikiViewScope').call() || {}
    const viewIds = new Set(Array.from(scope.viewSpaceIdList || []))
    const hidden = new Set(Array.from(scope.hiddenPageIdList || []))
    const mine = 'NOTES_' + me
    const today = fmt(Number(String(ec.user.nowTimestamp)), 'yyyy-MM-dd')
    const sorted = Array.from(items.entries()).sort((left, right) => right[1].millis - left[1].millis)
    for (const [id, item] of sorted) {
        if (pageList.length >= (limit || 5)) break
        const row = ec.entity.find('moqui.resource.wiki.WikiPage').condition('wikiPageId', id).one()
        if (row == null || hidden.has(id) || !viewIds.has(row.wikiSpaceId)) continue
        const isNotes = String(row.wikiSpaceId).startsWith('NOTES_')
        if (isNotes && (row.wikiSpaceId !== mine || !includeNotes)) continue
        const space = ec.entity.find('moqui.resource.wiki.WikiSpace').condition('wikiSpaceId', row.wikiSpaceId).useCache(true).one()
        const path = row.pagePath || ''
        const title = path ? path.substring(path.lastIndexOf('/') + 1) : (space?.description || row.wikiSpaceId)
        const day = fmt(item.millis, 'yyyy-MM-dd')
        pageList.push({wikiPageId: id, wikiSpaceId: row.wikiSpaceId, pagePath: path, title: title, isNotes: isNotes,
            spaceDescription: isNotes ? L('My notes') : (space?.description || row.wikiSpaceId), kind: item.kind,
            kindText: L(item.kind === 'changed' ? 'Changed' : 'Opened'), millis: item.millis,
            whenText: day === today ? fmt(item.millis, 'h:mm a') : fmt(item.millis, 'MMM d'),
            url: isNotes ? '/qapps/Commons/Notes?wikiPageId=' + encodeURIComponent(id) : '/qapps/Commons/Knowledge?wikiPageId=' + encodeURIComponent(id)})
    }
} catch (err) { failed = true; ec.logger.warn(`Recent pages not read: ${err}`) }

pageList = []
usedIndex = false
const needle = String(text || '').trim()
if (!needle) return
const me = ec.user.userId
const mine = me ? 'NOTES_' + me : null
const spaceId = scope === 'notes' ? mine : (wikiSpaceId || null)
if (scope === 'notes' && !mine) return
const out = ec.service.sync().name('org.moqui.resource.WikiServices.search#WikiPages').parameters({text: needle, wikiSpaceId: spaceId,
    limit: Math.min(Number(limit) || 25, 100)}).call() || {}
usedIndex = !!out.usedIndex
const fmt = (millis, pattern) => ec.l10n.format(new Date(Number(millis)), pattern)
for (const hit of Array.from(out.pageList || [])) {
    const isNotes = String(hit.wikiSpaceId).startsWith('NOTES_')
    if (scope === 'notes' ? hit.wikiSpaceId !== mine : isNotes) continue
    const millis = hit.updatedDate == null || hit.updatedDate === '' ? null : Number(String(hit.updatedDate))
    pageList.push({wikiPageId: hit.wikiPageId, wikiSpaceId: hit.wikiSpaceId, spaceDescription: hit.spaceDescription, pagePath: hit.pagePath || '',
        pageName: hit.pageName, title: hit.title || hit.pageName, updatedText: millis && !Number.isNaN(millis) ? fmt(millis, 'MMM d, yyyy') : ''})
}

optionList = []
const L = (text) => ec.l10n.localize(text)
const access = ec.service.sync().name('org.moqui.resource.WikiServices.get#WikiPageAccess').parameter('wikiSpaceId', wikiSpaceId).call() || {}
if (!access.canView) { ec.message.addError(L('Space not found')); return }
canUpdate = !!access.canUpdate
const out = ec.service.sync().name('org.moqui.resource.WikiServices.get#WikiSpacePages').parameter('wikiSpaceId', wikiSpaceId).call() || {}
optionList.push({value: '', label: L('Top level')})
const skip = excludePagePath ? String(excludePagePath) : null
for (const item of Array.from(out.allChildFileFlatList || [])) {
    const path = String(item.path || '')
    if (!path || (skip && (path === skip || path.startsWith(skip + '/')))) continue
    optionList.push({value: path, label: path.split('/').join(' / ')})
}

conflict = false
const L = (text) => ec.l10n.localize(text)
const ref = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#PageRef').parameters({wikiPageId: wikiPageId || null,
    wikiSpaceId: wikiSpaceId || null, pagePath: pagePath || '', need: 'update'}).call()
if (ec.message.hasError() || !ref?.found) return
const pageRef = ref.pageReference
const path = ref.pagePath || ''
const name = path ? path.substring(path.lastIndexOf('/') + 1) : ref.wikiSpaceId
const note = versionNote ? String(versionNote).trim().substring(0, 255) : null
if (collab && ref.wikiPageId) {
    // the co-edited document is the text: edits merged as they were made, so no conflict to check
    const out = ec.service.sync().name('org.moqui.resource.CollabServices.save#CollabDocument').parameters({documentKey: `WikiPage:${ref.wikiPageId}`,
        versionNote: note}).call()
    if (ec.message.hasError()) return
    wikiPageId = ref.wikiPageId
    wikiSpaceId = ref.wikiSpaceId
    pagePath = path
    versionName = out.versionName || null
    currentVersionName = versionName
    pageText = versionName ? ec.resource.getLocationReference(pageRef.location).getText() : null
} else {
    const current = ref.exists && pageRef.supportsVersion() ? (pageRef.getCurrentVersion()?.versionName ?? null) : null
    if (baseVersionName && !force && current && current !== baseVersionName) {
        const change = ec.resource.getLastChange(pageRef.location)
        const account = change?.userId ? ec.entity.find('moqui.security.UserAccount').condition('userId', change.userId).useCache(true).disableAuthz().one() : null
        conflict = true
        currentVersionName = current
        conflictText = ec.resource.expand('${name} saved this page since you opened it', '', {name: account ? (account.userFullName || account.username) : L('Someone')})
        wikiPageId = ref.wikiPageId
        wikiSpaceId = ref.wikiSpaceId
        pagePath = ref.pagePath
        return
    }
    const saved = ec.service.sync().name('org.moqui.resource.WikiServices.update#WikiPage').parameters({wikiSpaceId: ref.wikiSpaceId,
        wikiPageId: ref.wikiPageId || null, pagePath: path || null, pageName: name,
        parentPath: path.includes('/') ? path.substring(0, path.lastIndexOf('/')) : null, pageText: pageText ?? '', versionNote: note}).call()
    if (ec.message.hasError()) return
    wikiPageId = saved.wikiPageId || ref.wikiPageId
    wikiSpaceId = ref.wikiSpaceId
    pagePath = saved.pagePath ?? path
    versionName = saved.versionName || null
    currentVersionName = versionName || current
}
savedText = ec.l10n.format(ec.user.nowTimestamp, 'h:mm a')
if (versionName && note && !ref.isNotes && wikiPageId) {
    ec.message.pushErrors()
    try {
        const heading = String(pageText || '').match(/^\s{0,3}#{1,6}\s+(.+?)\s*#*\s*$/m)
        ec.service.sync().name('mantle.party.CommunicationServices.notify#RecordFollowers').parameters({
            recordEntityName: 'moqui.resource.wiki.WikiPage', recordId: wikiPageId, kind: 'changes',
            subject: (heading ? heading[1] : name) + ': ' + note, recordUrl: '/qapps/Commons/Knowledge?wikiPageId=' + encodeURIComponent(wikiPageId)}).call()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    } catch (err) {
        ec.logger.warn(`The followers of wiki page ${wikiPageId} were not told of version ${versionName}: ${err}`)
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}

const L = (text) => ec.l10n.localize(text)
const name = String(pageName || '').replace(/\s+/g, ' ').trim()
if (!name || !StringUtilities.isAlphaNumeric(name, ".,'-_:()!? ") || name === '.' || name === '..' || name.length > 100) {
    ec.message.addError(L("A page name has letters, digits, spaces and . , ' - _ : ( ) ! ? only"))
    return
}
let parent = String(parentPath || '').split('/').filter((part) => part).join('/')
if (parent === wikiSpaceId) parent = ''
// the parent page, or the space's home for a page at the top, which the user must see before anything is said of
// the paths there; whether they may add the page is update#WikiPage's to say
const parentRef = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#PageRef').parameters({wikiSpaceId: wikiSpaceId,
    pagePath: parent, need: 'view'}).call()
if (ec.message.hasError() || !parentRef?.found) return
if (parent && !parentRef.exists) { ec.message.addError(L('The parent page has not been made yet')); return }
parent = parentRef.pagePath || ''
const path = (parent ? parent + '/' : '') + name
// update#WikiPage writes over a page at the path: a new page is not made there
const taken = () => { ec.message.addError(ec.resource.expand('There is a page ${path} already', '', {path: path})) }
if (ec.entity.find('moqui.resource.wiki.WikiPage').condition('wikiSpaceId', wikiSpaceId).condition('pagePath', path).one() != null) return taken()
const file = ec.service.sync().name('org.moqui.resource.WikiServices.get#WikiPageFile').parameters({wikiSpaceId: wikiSpaceId, pagePath: path}).call()
if (ec.message.hasError()) return
if (file?.exists) return taken()
const saved = ec.service.sync().name('org.moqui.resource.WikiServices.update#WikiPage').parameters({wikiSpaceId: wikiSpaceId, pageName: name,
    parentPath: parent || null, wikiType: 'md', pageText: pageText ? String(pageText) : '# ' + name + '\n\n'}).call()
if (ec.message.hasError()) return
wikiPageId = saved.wikiPageId
pagePath = saved.pagePath
versionName = saved.versionName

pageCount = 0
failedPaths = []
const L = (text) => ec.l10n.localize(text)
const MAX_PAGES = 500
const src = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#PageRef').parameters({wikiPageId: wikiPageId, need: 'view'}).call()
if (ec.message.hasError() || !src?.found) return
const srcPath = src.pagePath || ''
if (!srcPath) { ec.message.addError(L('The home page of a space is copied with its space (Spaces, Clone)')); return }
if (!src.exists) { ec.message.addError(L('This page has no text yet to copy')); return }
const spaceId = toWikiSpaceId || src.wikiSpaceId
const name = String(toPageName || '').replace(/\s+/g, ' ').trim()
if (!name || !StringUtilities.isAlphaNumeric(name, ".,'-_:()!? ") || name === '.' || name === '..' || name.length > 100) {
    ec.message.addError(L("A page name has letters, digits, spaces and . , ' - _ : ( ) ! ? only"))
    return
}
let parent = String(toParentPath || '').split('/').map((part) => part.trim()).filter((part) => part).join('/')
if (parent === spaceId) parent = ''
// the place for the copy, which the user must see; whether they may add pages there is update#WikiPage's to say
const parentRef = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#PageRef').parameters({wikiSpaceId: spaceId,
    pagePath: parent, need: 'view'}).call()
if (ec.message.hasError() || !parentRef?.found) return
if (parent && !parentRef.exists) { ec.message.addError(L('The parent page has not been made yet')); return }
if (!parentRef.access?.canUpdate) {
    ec.message.addError(parentRef.access?.readOnly ? L('This space is a read-only mirror') : L('You may not add pages to this space')); return }
parent = parentRef.pagePath || ''
const path = (parent ? parent + '/' : '') + name
if (withChildren && spaceId === src.wikiSpaceId && (path === srcPath || path.startsWith(srcPath + '/'))) {
    ec.message.addError(L('A page is not copied under itself with the pages under it')); return }
const taken = () => { ec.message.addError(ec.resource.expand('There is a page ${path} already', '', {path: path})) }
if (ec.entity.find('moqui.resource.wiki.WikiPage').condition('wikiSpaceId', spaceId).condition('pagePath', path).one() != null) return taken()
const file = ec.service.sync().name('org.moqui.resource.WikiServices.get#WikiPageFile').parameters({wikiSpaceId: spaceId, pagePath: path}).call()
if (ec.message.hasError()) return
if (file?.exists) return taken()

// the pages to copy, top down: the page, then those under it the user may view (get#PageChildren)
const pages = [{fromPath: srcPath, toParent: parent, toName: name, toPath: path}]
if (withChildren) {
    const queue = [[srcPath, path]]
    while (queue.length && pages.length < MAX_PAGES) {
        const [from, to] = queue.shift()
        const kids = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#PageChildren').parameters({wikiSpaceId: src.wikiSpaceId,
            pagePath: from}).call()?.childList || []
        if (ec.message.hasError()) return
        for (const kid of kids) {
            if (pages.length >= MAX_PAGES) break
            const kidPath = to + '/' + kid.name
            pages.push({fromPath: kid.pagePath, toParent: to, toName: kid.name, toPath: kidPath})
            if (kid.hasChildren) queue.push([kid.pagePath, kidPath])
        }
    }
    if (pages.length >= MAX_PAGES) ec.logger.warn(`Knowledge: duplicate of ${src.wikiSpaceId}/${srcPath} stops at ${MAX_PAGES} pages`)
}
// each copy's first version names the page it was copied from
const noteOf = (fromPath) => ec.resource.expand('Copied from ${space}/${path}', '', {space: src.wikiSpaceId, path: fromPath}).substring(0, 255)
const failedUnder = []
for (const [index, item] of pages.entries()) {
    // a page under one that failed is not copied either
    if (failedUnder.some((failed) => item.toPath.startsWith(failed + '/'))) { failedPaths.push(item.fromPath); continue }
    ec.message.pushErrors()
    let out = null
    let why = null
    try {
        out = ec.service.sync().name('ironstone.commons.KnowledgeServices.copy#Page').parameters({fromWikiSpaceId: src.wikiSpaceId,
            fromPagePath: item.fromPath, toWikiSpaceId: spaceId, toParentPath: item.toParent, toPageName: item.toName, versionNote: noteOf(item.fromPath),
            usePublished: !!usePublished})
                .requireNewTransaction(true).call()
        if (ec.message.hasError()) why = ec.message.getErrorsString()
    } catch (err) {
        why = err && err.message ? err.message : String(err)
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
    if (why) {
        if (index === 0) { ec.message.addError(why); return }
        ec.logger.error(`Knowledge: page ${src.wikiSpaceId}/${item.fromPath} was not copied to ${spaceId}/${item.toPath}, it and the pages under it are left out: ${why}`)
        failedPaths.push(item.fromPath)
        failedUnder.push(item.toPath)
        continue
    }
    for (const fileName of Array.from(out?.failedFiles || [])) failedPaths.push(item.fromPath + '/' + fileName)
    if (index === 0) { wikiPageId = out.wikiPageId; pagePath = out.pagePath }
    pageCount++
}
wikiSpaceId = spaceId

const L = (text) => ec.l10n.localize(text)
const ref = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#PageRef').parameters({wikiPageId: wikiPageId, need: 'update'}).call()
if (ec.message.hasError() || !ref?.found) return
const path = ref.pagePath || ''
if (!path) { ec.message.addError(L('The home page of a space keeps its name')); return }
const name = String(pageName || '').replace(/\s+/g, ' ').trim()
const moved = ec.service.sync().name('org.moqui.resource.WikiServices.move#WikiPage').parameters({wikiPageId: wikiPageId,
    toWikiSpaceId: ref.wikiSpaceId, toParentPath: path.includes('/') ? path.substring(0, path.lastIndexOf('/')) : '', toPageName: name}).call()
if (ec.message.hasError()) return
wikiSpaceId = moved.wikiSpaceId
pagePath = moved.pagePath

const L = (text) => ec.l10n.localize(text)
const ref = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#PageRef').parameters({wikiPageId: wikiPageId, need: 'update'}).call()
if (ec.message.hasError() || !ref?.found) return
const parentOf = (path) => path.includes('/') ? path.substring(0, path.lastIndexOf('/')) : ''
const path = ref.pagePath || ''
oldPagePath = path
wikiSpaceId = ref.wikiSpaceId
if (!path) { ec.message.addError(L('The home page of a space is not moved')); return }
const target = String(targetPagePath || '').split('/').filter((part) => part).join('/')
if (!['before', 'after', 'inside'].includes(position)) { ec.message.addError(L('Drop before, after or inside a page')); return }
if (target === path) { pagePath = path; return }
const newParent = position === 'inside' ? target : parentOf(target)
if (newParent === path || newParent.startsWith(path + '/')) { ec.message.addError(L('A page cannot move under itself')); return }
const name = path.substring(path.lastIndexOf('/') + 1)
pagePath = path
if (parentOf(path) !== newParent) {
    const moved = ec.service.sync().name('org.moqui.resource.WikiServices.move#WikiPage').parameters({wikiPageId: wikiPageId,
        toWikiSpaceId: ref.wikiSpaceId, toParentPath: newParent, toPageName: name}).call()
    if (ec.message.hasError()) return
    pagePath = moved.pagePath
}
if (position === 'inside') return
const spaceAccess = ec.service.sync().name('org.moqui.resource.WikiServices.get#WikiPageAccess').parameter('wikiSpaceId', ref.wikiSpaceId).call() || {}
if (!spaceAccess.canUpdate) return
// the siblings in their order, the page moved before or after the target, each given its place
const children = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#PageChildren').parameters({wikiSpaceId: ref.wikiSpaceId,
    pagePath: newParent}).call()?.childList || []
const order = children.map((child) => child.pagePath).filter((childPath) => childPath !== pagePath)
const at = order.indexOf(target)
order.splice(at < 0 ? order.length : (position === 'before' ? at : at + 1), 0, pagePath)
order.forEach((childPath, index) => {
    const idOut = ec.service.sync().name('org.moqui.resource.WikiServices.get#WikiPageId').parameters({wikiSpaceId: ref.wikiSpaceId,
        pagePath: childPath, createIfMissing: true}).call()
    const sequenceNum = (index + 1) * 10
    if (idOut?.wikiPageId && Number(idOut.wikiPage?.sequenceNum) !== sequenceNum)
        ec.service.sync().name('update#moqui.resource.wiki.WikiPage').parameters({wikiPageId: idOut.wikiPageId, sequenceNum: sequenceNum}).call()
})

const ref = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#PageRef').parameters({wikiPageId: wikiPageId, need: 'update'}).call()
if (ec.message.hasError() || !ref?.found) return
const out = ec.service.sync().name('org.moqui.resource.WikiServices.delete#WikiPage').parameters({wikiPageId: wikiPageId, deleteAttachments: true}).call()
if (ec.message.hasError()) return
wikiSpaceId = out.wikiSpaceId || ref.wikiSpaceId
parentPath = out.pagePath || ''

const L = (text) => ec.l10n.localize(text)
const ref = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#PageRef').parameters({wikiPageId: wikiPageId, need: 'update'}).call()
if (ec.message.hasError() || !ref?.found) return
if (ref.isNotes) { ec.message.addError(L('A note is not published')); return }
// the current version by default: an empty name would take the page's published version away
const name = versionName || (ref.exists && ref.pageReference.supportsVersion() ? ref.pageReference.getCurrentVersion()?.versionName : null)
if (!name) { ec.message.addError(L('This page keeps no versions to publish')); return }
const out = ec.service.sync().name('org.moqui.resource.WikiServices.set#PublishedVersion').parameters({wikiPageId: wikiPageId,
    publishedVersionName: name}).call()
if (ec.message.hasError()) return
publishedVersionName = out.publishedVersionName

versionList = []
historyList = []
const ref = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#PageRef').parameters({wikiPageId: wikiPageId || null,
    wikiSpaceId: wikiSpaceId || null, pagePath: pagePath || '', need: 'view'}).call()
if (ec.message.hasError() || !ref?.found || !ref.exists) return
const out = ec.service.sync().name('org.moqui.resource.WikiServices.get#WikiPageHistory').parameters({wikiPageId: ref.wikiPageId || null,
    wikiSpaceId: ref.wikiSpaceId, pagePath: ref.pagePath || ''}).call()
if (ec.message.hasError() || out == null) return
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    const text = String(value)
    if (/^-?\d+$/.test(text)) return Number(text)
    const parsed = Date.parse(text)
    return Number.isNaN(parsed) ? null : parsed
}
const fmt = (millis) => millis == null ? '' : ec.l10n.format(new Date(Number(millis)), 'MMM d, yyyy h:mm a')
currentVersionName = out.currentVersionName
publishedVersionName = out.publishedVersionName
storage = out.storage
canRestore = !!ref.access.canUpdate && !!ref.wikiPageId
canPublish = !!ref.access.canUpdate && !!ref.wikiPageId && !ref.isNotes
versionList = Array.from(out.versionList || []).map((version) => {
    const millis = toMillis(version.versionDate)
    const note = version.note ? String(version.note) : ''
    return {versionName: version.versionName, shortName: version.shortName, previousVersionName: version.previousVersionName || null,
        millis: millis, dateText: fmt(millis), userId: version.userId, userName: version.userName, note: note.split('\n')[0],
        noteMore: note.includes('\n') ? note.substring(note.indexOf('\n') + 1).trim() : null, isCurrent: !!version.isCurrent,
        isPublished: !!version.isPublished, movedFrom: version.movedFrom || null}
})
historyList = Array.from(out.historyList || []).map((row) => Object.assign({}, row, {dateText: fmt(toMillis(row.changeDateTime))}))

const ref = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#PageRef').parameters({wikiPageId: wikiPageId || null,
    wikiSpaceId: wikiSpaceId || null, pagePath: pagePath || '', need: 'view'}).call()
if (ec.message.hasError() || !ref?.found) return
const out = ec.service.sync().name('org.moqui.resource.WikiServices.get#WikiPageVersionDiff').parameters({wikiPageId: ref.wikiPageId || null,
    wikiSpaceId: ref.wikiSpaceId, pagePath: ref.pagePath || '', fromVersionName: fromVersionName || null, toVersionName: toVersionName || null}).call()
if (ec.message.hasError() || out == null) return
const short = (name) => name == null ? null : String(name).length > 12 ? String(name).substring(0, 10) : String(name)
fromVersionName = out.fromVersionName
toVersionName = out.toVersionName
fromShort = short(fromVersionName)
toShort = short(toVersionName)
html = out.diff?.html || ''
stats = out.diff?.stats || {}

