const L = (text) => ec.l10n.localize(text)
const ref = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#PageRef').parameters({wikiPageId: wikiPageId, need: 'update'}).call()
if (ec.message.hasError() || !ref?.found) return
if (ref.isNotes) { ec.message.addError(L('A note is not reviewed')); return }
const ids = (Array.isArray(reviewerUserIds) ? reviewerUserIds : String(reviewerUserIds || '').split(','))
        .map((id) => String(id || '').trim()).filter((id) => id && id !== 'null')
let due = null
if (dueDate) {
    const text = String(dueDate).trim().substring(0, 10)
    if (!/^\d{4}-\d{2}-\d{2}$/.test(text)) { ec.message.addError(L('The due date is a day: yyyy-MM-dd')); return }
    due = ec.l10n.parseTimestamp(text + ' 23:59:59.000', 'yyyy-MM-dd HH:mm:ss.SSS')
}
const out = ec.service.sync().name('org.moqui.resource.WikiServices.request#WikiPageReview').parameters({wikiPageId: wikiPageId,
    versionName: versionName || null, reviewerUserIdList: ids, dueDate: due, note: note ? String(note).trim() : null,
    link: '/qapps/Commons/Knowledge?wikiPageId=' + encodeURIComponent(wikiPageId) + '&review=open'}).call()
if (ec.message.hasError()) return
wikiPageReviewId = out.wikiPageReviewId
wikiPageReviewIdList = out.wikiPageReviewIdList

const out = ec.service.sync().name('org.moqui.resource.WikiServices.find#WikiPageReviews').parameters({filter: filter || 'toDo',
    statusId: statusId || 'WprRequested', wikiSpaceId: wikiSpaceId || null, wikiPageId: wikiPageId || null, limit: 200}).call() || {}
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    const text = String(value)
    if (/^-?\d+$/.test(text)) return Number(text)
    const parsed = Date.parse(text)
    return Number.isNaN(parsed) ? null : parsed
}
const fmt = (millis, pattern) => millis == null ? '' : ec.l10n.format(new Date(Number(millis)), pattern)
const now = Number(String(ec.user.nowTimestamp))
const me = ec.user.userId
reviewList = Array.from(out.reviewList || []).filter((review) => !String(review.wikiSpaceId).startsWith('NOTES_')).map((review) => {
    const requested = toMillis(review.requestedDate)
    const due = toMillis(review.dueDate)
    const decided = toMillis(review.decidedDate)
    return Object.assign({}, review, {requestedText: fmt(requested, 'MMM d, h:mm a'), dueText: fmt(due, 'MMM d'),
        overdue: due != null && review.statusId === 'WprRequested' && due < now, decidedText: fmt(decided, 'MMM d, h:mm a'),
        reviewerText: review.reviewerName || ec.l10n.localize('Anyone who may edit'), isRequester: review.requestedByUserId === me,
        canCancel: review.statusId === 'WprRequested' && review.requestedByUserId === me,
        url: '/qapps/Commons/Knowledge?wikiPageId=' + encodeURIComponent(review.wikiPageId) + '&review=' + encodeURIComponent(review.wikiPageReviewId)})
})
reviewCount = reviewList.length

const L = (text) => ec.l10n.localize(text)
const ref = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#PageRef').parameters({wikiPageId: wikiPageId, need: 'update'}).call()
if (ec.message.hasError() || !ref?.found) return
const raw = Array.isArray(tags) ? tags : String(tags || '').split(',')
const wanted = []
for (const tag of raw) {
    const name = String(tag || '').replace(/\s+/g, ' ').trim().substring(0, 60)
    if (!name || name.toLowerCase() === 'pinned' || wanted.some((known) => known.toLowerCase() === name.toLowerCase())) continue
    wanted.push(name)
}
if (wanted.length > 20) { ec.message.addError(L('A page has 20 tags at most')); return }
const categories = Array.from(ec.entity.find('moqui.resource.wiki.WikiPageCategory').list())
const categoryOf = (name) => {
    let category = categories.find((row) => row.categoryName === name) || categories.find((row) => String(row.categoryName || '').toLowerCase() === name.toLowerCase())
    if (category == null) {
        category = ec.entity.makeValue('moqui.resource.wiki.WikiPageCategory')
        category.setSequencedIdPrimary()
        category.categoryName = name
        category.create()
        categories.push(category)
    }
    return category.wikiPageCategoryId
}
const wantedIds = wanted.map(categoryOf)
const now = ec.user.nowTimestamp
const members = Array.from(ec.entity.find('moqui.resource.wiki.WikiPageCategoryMember').condition('wikiPageId', wikiPageId).list())
for (const member of members) {
    if (member.wikiPageCategoryId === 'Pinned') continue
    if (!wantedIds.includes(member.wikiPageCategoryId)) member.delete()
    else if (member.thruDate != null) { member.thruDate = null; member.update() }
}
for (const categoryId of wantedIds) {
    if (members.some((member) => member.wikiPageCategoryId === categoryId)) continue
    const member = ec.entity.makeValue('moqui.resource.wiki.WikiPageCategoryMember')
    member.setFields({wikiPageCategoryId: categoryId, wikiPageId: wikiPageId, fromDate: now}, true, null, null)
    member.create()
}
tagList = wanted.sort((a, b) => a.localeCompare(b))

const ref = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#PageRef').parameters({wikiPageId: wikiPageId, need: 'update'}).call()
if (ec.message.hasError() || !ref?.found) return
if (ec.entity.find('moqui.resource.wiki.WikiPageCategory').condition('wikiPageCategoryId', 'Pinned').one() == null) {
    const category = ec.entity.makeValue('moqui.resource.wiki.WikiPageCategory')
    category.setFields({wikiPageCategoryId: 'Pinned', categoryName: 'Pinned'}, true, null, null)
    category.create()
}
const member = ec.entity.find('moqui.resource.wiki.WikiPageCategoryMember').condition({wikiPageCategoryId: 'Pinned', wikiPageId: wikiPageId}).one()
if (pinned && member == null) {
    const row = ec.entity.makeValue('moqui.resource.wiki.WikiPageCategoryMember')
    row.setFields({wikiPageCategoryId: 'Pinned', wikiPageId: wikiPageId, fromDate: ec.user.nowTimestamp}, true, null, null)
    row.create()
} else if (pinned && member.thruDate != null) {
    member.thruDate = null
    member.update()
} else if (!pinned && member != null) {
    member.delete()
}

