const joins = {'mantle.work.effort.WorkEffort': ['mantle.work.effort.WikiPageWorkEffort', 'workEffortId'],
    'mantle.request.Request': ['mantle.request.WikiPageRequest', 'requestId']}
const join = joins[recordEntityName]
if (!join) return
const ref = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#PageRef').parameters({wikiPageId: wikiPageId, need: 'update'}).call()
if (ec.message.hasError() || !ref?.found) return
ec.entity.find(join[0]).condition({wikiPageId: wikiPageId, [join[1]]: recordId}).deleteAll()

optionList = []
ec.message.pushErrors()
try {
    const out = ec.service.sync().name('ironstone.comms.InboxServices.search#LinkRecords').parameter('term', term || '').call() || {}
    optionList = Array.from(out.optionList || []).filter((option) => ['mantle.work.effort.WorkEffort', 'mantle.request.Request']
            .includes(option.recordEntityName)).map((option) => ({value: option.value, label: option.label}))
} catch (err) {
    ec.logger.warn(`Page record search for ${term} failed: ${err}`)
} finally { ec.message.clearErrors(); ec.message.popErrors() }

noteList = []
tagList = []
totalCount = 0
const L = (text) => ec.l10n.localize(text)
const space = ec.service.sync().name('org.moqui.resource.WikiServices.ensure#UserNotesSpace').call()
if (ec.message.hasError() || !space?.wikiSpaceId) return
wikiSpaceId = space.wikiSpaceId
const out = ec.service.sync().name('org.moqui.resource.WikiServices.get#WikiSpacePages').parameters({wikiSpaceId: wikiSpaceId, includeDetail: true}).call()
if (ec.message.hasError()) return
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    const text = String(value)
    if (/^-?\d+$/.test(text)) return Number(text)
    const parsed = Date.parse(text)
    return Number.isNaN(parsed) ? null : parsed
}
const fmt = (millis, pattern) => ec.l10n.format(new Date(Number(millis)), pattern)
const nowMillis = Number(String(ec.user.nowTimestamp))
const today = fmt(nowMillis, 'yyyy-MM-dd')
const year = fmt(nowMillis, 'yyyy')
const whenText = (millis) => millis == null ? '' : fmt(millis, 'yyyy-MM-dd') === today ? fmt(millis, 'h:mm a')
        : fmt(millis, 'yyyy') === year ? fmt(millis, 'MMM d') : fmt(millis, 'MMM d, yyyy')
let all = Array.from(out.allChildFileFlatList || []).filter((item) => item.path && item.wikiPageId).map((item) => {
    const millis = toMillis(item.modifiedDate)
    return {wikiPageId: item.wikiPageId, pagePath: item.path, title: item.title || item.name, snippet: item.snippet || '',
        millis: millis, whenText: whenText(millis), pinned: !!item.pinned,
        tags: Array.from(item.categoryNameList || []).filter((name) => name !== 'Pinned')}
})
totalCount = all.length
const counts = new Map()
for (const note of all) for (const name of note.tags) counts.set(name, (counts.get(name) || 0) + 1)
tagList = Array.from(counts.entries()).map(([name, count]) => ({name: name, count: count})).sort((a, b) => a.name.localeCompare(b.name))
const needle = String(text || '').trim()
if (needle) {
    const lower = needle.toLowerCase()
    const hits = new Set()
    ec.message.pushErrors()
    try {
        const found = ec.service.sync().name('ironstone.commons.KnowledgeServices.search#Pages').parameters({text: needle, scope: 'notes', limit: 100}).call()
        for (const hit of Array.from(found?.pageList || [])) hits.add(hit.wikiPageId)
    } catch (err) {
        ec.logger.warn(`Notes search for ${needle} failed, the titles only: ${err}`)
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
    all = all.filter((note) => hits.has(note.wikiPageId) || note.title.toLowerCase().includes(lower) || note.snippet.toLowerCase().includes(lower)
            || note.tags.some((name) => name.toLowerCase().includes(lower)))
}
if (tag) all = all.filter((note) => note.tags.includes(tag))
all.sort((left, right) => (right.pinned ? 1 : 0) - (left.pinned ? 1 : 0) || (right.millis || 0) - (left.millis || 0) || left.title.localeCompare(right.title))
noteList = all

const L = (text) => ec.l10n.localize(text)
const space = ec.service.sync().name('org.moqui.resource.WikiServices.ensure#UserNotesSpace').call()
if (ec.message.hasError() || !space?.wikiSpaceId) return
wikiSpaceId = space.wikiSpaceId
const cleanTitle = String(title || '').replace(/[^\p{L}\p{Nd}_.\-,':()!? ]+/gu, ' ').replace(/\s+/g, ' ').trim().substring(0, 80)
const base = cleanTitle || (L('Note') + ' ' + ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd HH.mm'))
const inUse = (name) => ec.entity.find('moqui.resource.wiki.WikiPage').condition('wikiSpaceId', wikiSpaceId).condition('pagePath', name).count() > 0
let name = base
for (let n = 2; inUse(name) && n < 100; n++) name = `${base} (${n})`
const text = pageText != null && String(pageText).length ? String(pageText) : (cleanTitle ? '# ' + String(title).trim() + '\n\n' : '')
const saved = ec.service.sync().name('ironstone.commons.KnowledgeServices.create#Page').parameters({wikiSpaceId: wikiSpaceId, pageName: name,
    pageText: text.length ? text : ' '}).call()
if (ec.message.hasError()) return
wikiPageId = saved.wikiPageId
pagePath = saved.pagePath

spaceList = []
const L = (text) => ec.l10n.localize(text)
isAdmin = ec.user.isInGroup('ADMIN')
const scope = ec.service.sync().name('org.moqui.resource.WikiServices.get#WikiViewScope').call() || {}
const viewIds = new Set(Array.from(scope.viewSpaceIdList || []))
const storageText = (access) => access.storage === 'git' ? (access.repositoryKind === 'remote' ? L('Git mirror (read only)')
        : access.repositoryKind === 'local' ? L('Git on disk') : L('Git in the database')) : (access.storage === 'db' ? L('Database files') : L('Other'))
for (const space of Array.from(ec.entity.find('moqui.resource.wiki.WikiSpace').orderBy('description,wikiSpaceId').list())) {
    if (!viewIds.has(space.wikiSpaceId) || String(space.wikiSpaceId).startsWith('NOTES_')) continue
    const access = ec.service.sync().name('org.moqui.resource.WikiServices.get#WikiPageAccess').parameter('wikiSpaceId', space.wikiSpaceId).call() || {}
    const members = ec.entity.find('moqui.resource.wiki.WikiSpaceUser').condition('wikiSpaceId', space.wikiSpaceId).count()
    const pages = ec.entity.find('moqui.resource.wiki.WikiPage').condition('wikiSpaceId', space.wikiSpaceId).count()
    const view = space.restrictView === 'Y' ? L('Members') : L('Everyone')
    const update = space.restrictUpdate === 'Y' ? L('members who may edit') : L('everyone')
    spaceList.push({wikiSpaceId: space.wikiSpaceId, description: space.description || space.wikiSpaceId, pageCount: pages, memberCount: members,
        visibilityText: ec.resource.expand('${view} read · ${update} write', '', {view: view, update: update}),
        restrictView: space.restrictView === 'Y', restrictUpdate: space.restrictUpdate === 'Y', publicPageUrl: space.publicPageUrl || null,
        storage: access.storage || null, repositoryKind: access.repositoryKind || null, storageText: storageText(access),
        canUpdate: !!access.canUpdate, canAdmin: !!access.canAdmin,
        youText: access.canAdmin ? L('you administer it') : access.canUpdate ? L('you may edit') : L('you may read')})
}

const L = (text) => ec.l10n.localize(text)
const kinds = {db: null, gitdb: 'db', gitlocal: 'local', mirror: 'remote'}
if (!(storage in kinds)) { ec.message.addError(L('Choose where the space keeps its pages')); return }
if (storage === 'mirror' && !ec.user.isInGroup('ADMIN')) { ec.message.addError(L('Only an administrator adds a mirror')); return }
const flag = (value) => value === 'Y' || value === true || value === 'true' ? 'Y' : 'N'
const id = String(wikiSpaceId || '').trim()
const title = String(description || '').trim()
const made = ec.service.sync().name('org.moqui.resource.WikiServices.create#WikiSpace').parameters({wikiSpaceId: id, description: title,
    repositoryKind: kinds[storage], remoteUrl: storage === 'mirror' ? (remoteUrl || null) : null, restrictView: flag(restrictView),
    restrictUpdate: flag(restrictUpdate), allowAnyHtml: 'N'}).call()
if (ec.message.hasError()) return
wikiSpaceId = made.wikiSpaceId
repositoryId = made.repositoryId || null
if (storage !== 'mirror') ec.service.sync().name('org.moqui.resource.WikiServices.update#WikiPage').parameters({wikiSpaceId: wikiSpaceId,
    pageName: wikiSpaceId, pageText: '# ' + title + '\n\n' + L('The home page of this space: say what the space is for and link to its pages.') + '\n',
    versionNote: L('New space')}).call()

const L = (text) => ec.l10n.localize(text)
const kinds = {db: null, gitdb: 'db', gitlocal: 'local'}
if (!(storage in kinds)) { ec.message.addError(L('A clone is kept in database files or a git repository')); return }
if (String(baseWikiSpaceId).startsWith('NOTES_')) { ec.message.addError(L('Space not found')); return }
const out = ec.service.sync().name('org.moqui.resource.WikiServices.clone#WikiSpace').parameters({baseWikiSpaceId: baseWikiSpaceId,
    wikiSpaceId: String(wikiSpaceId || '').trim(), description: description ? String(description).trim() : null, repositoryKind: kinds[storage],
    copyHistory: !!copyHistory, copyAttachments: copyAttachments !== false}).call()
if (ec.message.hasError()) return
wikiSpaceId = out.wikiSpaceId
versionCount = out.versionCount || 0

memberList = []
restrictedPageList = []
const L = (text) => ec.l10n.localize(text)
if (String(wikiSpaceId).startsWith('NOTES_')) { ec.message.addError(L('Space not found')); return }
const row = ec.entity.find('moqui.resource.wiki.WikiSpace').condition('wikiSpaceId', wikiSpaceId).one()
const access = row ? (ec.service.sync().name('org.moqui.resource.WikiServices.get#WikiPageAccess').parameter('wikiSpaceId', wikiSpaceId).call() || {}) : {}
if (row == null || !access.canView) { ec.message.addError(L('Space not found')); return }
const users = {}
const userName = (userId) => {
    if (!userId) return null
    if (!(userId in users)) {
        const account = ec.entity.find('moqui.security.UserAccount').condition('userId', userId).useCache(true).disableAuthz().one()
        users[userId] = account ? (account.userFullName || account.username || userId) : userId
    }
    return users[userId]
}
const permissionOf = (member) => member.allowAdmin === 'Y' ? 'admin' : member.allowUpdate === 'Y' ? 'edit' : member.allowView === 'Y' ? 'view' : 'none'
const permissionText = {admin: L('Administer'), edit: L('Edit'), view: L('Read'), none: L('No access')}
space = {wikiSpaceId: row.wikiSpaceId, description: row.description || '', publicPageUrl: row.publicPageUrl || '',
    publicAttachmentUrl: row.publicAttachmentUrl || '', restrictView: row.restrictView === 'Y' ? 'Y' : 'N',
    restrictUpdate: row.restrictUpdate === 'Y' ? 'Y' : 'N', allowAnyHtml: row.allowAnyHtml === 'Y' ? 'Y' : 'N',
    rootPageLocation: row.rootPageLocation, storage: access.storage, repositoryId: access.repositoryId || null,
    repositoryKind: access.repositoryKind || null, readOnly: !!access.readOnly, canAdmin: !!access.canAdmin, canUpdate: !!access.canUpdate,
    isAdminGroup: ec.user.isInGroup('ADMIN')}
space.storageText = space.storage === 'git' ? ec.resource.expand('Git repository ${repositoryId} (${kind})', '', {repositoryId: space.repositoryId,
        kind: space.repositoryKind === 'remote' ? L('a read-only mirror') : space.repositoryKind === 'local' ? L('on disk') : L('in the database')})
        : space.storage === 'db' ? L('Database files') : L('Other')
if (space.storage === 'git' && space.repositoryId) {
    try {
        const repo = ec.entity.find('moqui.resource.GitRepository').condition('repositoryId', space.repositoryId).disableAuthz().one()
        space.branch = repo?.branch || null
        space.remoteUrl = repo?.remoteUrl || null
        const head = ec.resource.getLastChange('git://' + space.repositoryId + '/')
        space.headCommit = head?.versionName ? String(head.versionName).substring(0, 10) : null
        space.headNote = head?.note ? String(head.note).split('\n')[0] : null
    } catch (err) { ec.logger.warn(`Space ${wikiSpaceId}: the repository not read: ${err}`) }
}
for (const member of Array.from(ec.entity.find('moqui.resource.wiki.WikiSpaceUser').condition('wikiSpaceId', wikiSpaceId).list())) {
    const permission = permissionOf(member)
    memberList.push({userId: member.userId, name: userName(member.userId), permission: permission, permissionText: permissionText[permission],
        isMe: member.userId === ec.user.userId})
}
memberList.sort((a, b) => String(a.name).localeCompare(String(b.name)))
const cf = ec.entity.conditionFactory
for (const page of Array.from(ec.entity.find('moqui.resource.wiki.WikiPage').condition('wikiSpaceId', wikiSpaceId)
        .condition(cf.makeCondition([cf.makeCondition('restrictView', 'equals', 'Y'), cf.makeCondition('restrictUpdate', 'equals', 'Y')], 'or'))
        .orderBy('pagePath').list())) {
    const pageAccess = ec.service.sync().name('org.moqui.resource.WikiServices.get#WikiPageAccess').parameter('wikiPageId', page.wikiPageId).call() || {}
    if (!pageAccess.canView && !access.canAdmin) continue
    const pageUsers = Array.from(ec.entity.find('moqui.resource.wiki.WikiPageUser').condition('wikiPageId', page.wikiPageId).list())
            .map((user) => ({userId: user.userId, name: userName(user.userId), permission: user.allowUpdate === 'Y' ? 'edit' : user.allowView === 'Y' ? 'view' : 'none'}))
    restrictedPageList.push({wikiPageId: page.wikiPageId, pagePath: page.pagePath || '', restrictView: page.restrictView === 'Y',
        restrictUpdate: page.restrictUpdate === 'Y', userList: pageUsers,
        usersText: pageUsers.map((user) => user.name + ' (' + permissionText[user.permission === 'edit' ? 'edit' : user.permission === 'view' ? 'view' : 'none'] + ')').join(', ')})
}

const L = (text) => ec.l10n.localize(text)
const access = ec.service.sync().name('org.moqui.resource.WikiServices.get#WikiPageAccess').parameter('wikiSpaceId', wikiSpaceId).call() || {}
if (!access.canView || String(wikiSpaceId).startsWith('NOTES_')) { ec.message.addError(L('Space not found')); return }
if (!access.canAdmin) { ec.message.addError(L('Only an administrator of this space may do that')); return }
const url = (value) => {
    const text = String(value || '').trim()
    if (text && !/^https?:\/\/[^\s<>"']+$/i.test(text)) { ec.message.addError(L('A public URL starts with http:// or https://')); return null }
    return text || null
}
const fields = {wikiSpaceId: wikiSpaceId}
if (description != null) fields.description = String(description).trim() || wikiSpaceId
if (publicPageUrl != null) fields.publicPageUrl = url(publicPageUrl)
if (publicAttachmentUrl != null) fields.publicAttachmentUrl = url(publicAttachmentUrl)
if (ec.message.hasError()) return
if (restrictView != null && restrictView !== '') fields.restrictView = restrictView === 'Y' ? 'Y' : 'N'
if (restrictUpdate != null && restrictUpdate !== '') fields.restrictUpdate = restrictUpdate === 'Y' ? 'Y' : 'N'
if (allowAnyHtml != null && allowAnyHtml !== '') {
    const wanted = allowAnyHtml === 'Y' ? 'Y' : 'N'
    const space = ec.entity.find('moqui.resource.wiki.WikiSpace').condition('wikiSpaceId', wikiSpaceId).one()
    if (wanted !== (space?.allowAnyHtml === 'Y' ? 'Y' : 'N')) {
        if (!ec.user.isInGroup('ADMIN')) { ec.message.addError(L('Only a system administrator allows any HTML')); return }
        fields.allowAnyHtml = wanted
    }
}
ec.service.sync().name('update#moqui.resource.wiki.WikiSpace').parameters(fields).call()

const L = (text) => ec.l10n.localize(text)
const access = ec.service.sync().name('org.moqui.resource.WikiServices.get#WikiPageAccess').parameter('wikiSpaceId', wikiSpaceId).call() || {}
if (!access.canView || String(wikiSpaceId).startsWith('NOTES_')) { ec.message.addError(L('Space not found')); return }
if (!access.canAdmin) { ec.message.addError(L('Only an administrator of this space may do that')); return }
if (!['view', 'edit', 'admin'].includes(permission)) { ec.message.addError(L('A member may read, edit or administer')); return }
if (ec.entity.find('moqui.security.UserAccount').condition('userId', userId).disableAuthz().one() == null) { ec.message.addError(L('No such user')); return }
const flags = {allowView: 'Y', allowUpdate: permission === 'view' ? 'N' : 'Y', allowAdmin: permission === 'admin' ? 'Y' : 'N'}
const existing = ec.entity.find('moqui.resource.wiki.WikiSpaceUser').condition({wikiSpaceId: wikiSpaceId, userId: userId}).one()
if (existing != null && existing.allowAdmin === 'Y' && flags.allowAdmin !== 'Y') {
    const admins = ec.entity.find('moqui.resource.wiki.WikiSpaceUser').condition({wikiSpaceId: wikiSpaceId, allowAdmin: 'Y'}).count()
    if (admins <= 1) { ec.message.addError(L('A space keeps at least one administrator')); return }
}
const keys = {wikiSpaceId: wikiSpaceId, userId: userId}
if (existing == null) ec.service.sync().name('create#moqui.resource.wiki.WikiSpaceUser').parameters(Object.assign({receiveNotifications: 'N'}, keys, flags)).call()
else ec.service.sync().name('update#moqui.resource.wiki.WikiSpaceUser').parameters(Object.assign({}, keys, flags)).call()

const L = (text) => ec.l10n.localize(text)
const access = ec.service.sync().name('org.moqui.resource.WikiServices.get#WikiPageAccess').parameter('wikiSpaceId', wikiSpaceId).call() || {}
if (!access.canView || String(wikiSpaceId).startsWith('NOTES_')) { ec.message.addError(L('Space not found')); return }
if (!access.canAdmin) { ec.message.addError(L('Only an administrator of this space may do that')); return }
const existing = ec.entity.find('moqui.resource.wiki.WikiSpaceUser').condition({wikiSpaceId: wikiSpaceId, userId: userId}).one()
if (existing == null) return
if (existing.allowAdmin === 'Y' &&
        ec.entity.find('moqui.resource.wiki.WikiSpaceUser').condition({wikiSpaceId: wikiSpaceId, allowAdmin: 'Y'}).count() <= 1) {
    ec.message.addError(L('A space keeps at least one administrator'))
    return
}
existing.delete()

const ref = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#PageRef').parameters({wikiPageId: wikiPageId, need: 'admin'}).call()
if (ec.message.hasError() || !ref?.found) return
const fields = {wikiPageId: wikiPageId}
if (restrictView != null && restrictView !== '') fields.restrictView = restrictView === 'Y' ? 'Y' : 'N'
if (restrictUpdate != null && restrictUpdate !== '') fields.restrictUpdate = restrictUpdate === 'Y' ? 'Y' : 'N'
if (ec.user.userId && fields.restrictView === 'Y') {
    const mine = ec.entity.find('moqui.resource.wiki.WikiPageUser').condition({wikiPageId: wikiPageId, userId: ec.user.userId}).one()
    if (mine == null) ec.service.sync().name('create#moqui.resource.wiki.WikiPageUser').parameters({wikiPageId: wikiPageId, userId: ec.user.userId,
        allowView: 'Y', allowUpdate: 'Y', receiveNotifications: 'N'}).call()
    else if (mine.allowView !== 'Y' || mine.allowUpdate !== 'Y') ec.service.sync().name('update#moqui.resource.wiki.WikiPageUser')
            .parameters({wikiPageId: wikiPageId, userId: ec.user.userId, allowView: 'Y', allowUpdate: 'Y'}).call()
}
ec.service.sync().name('update#moqui.resource.wiki.WikiPage').parameters(fields).call()

const L = (text) => ec.l10n.localize(text)
const ref = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#PageRef').parameters({wikiPageId: wikiPageId, need: 'admin'}).call()
if (ec.message.hasError() || !ref?.found) return
if (ec.entity.find('moqui.security.UserAccount').condition('userId', userId).disableAuthz().one() == null) { ec.message.addError(L('No such user')); return }
const flags = {allowView: 'Y', allowUpdate: permission === 'edit' ? 'Y' : 'N'}
const keys = {wikiPageId: wikiPageId, userId: userId}
if (ec.entity.find('moqui.resource.wiki.WikiPageUser').condition(keys).one() == null)
    ec.service.sync().name('create#moqui.resource.wiki.WikiPageUser').parameters(Object.assign({receiveNotifications: 'N'}, keys, flags)).call()
else ec.service.sync().name('update#moqui.resource.wiki.WikiPageUser').parameters(Object.assign({}, keys, flags)).call()

const ref = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#PageRef').parameters({wikiPageId: wikiPageId, need: 'admin'}).call()
if (ec.message.hasError() || !ref?.found) return
ec.entity.find('moqui.resource.wiki.WikiPageUser').condition({wikiPageId: wikiPageId, userId: userId}).deleteAll()
